commands:
for f in rosterkit/notices.py tests/test_notices.py; do awk -v name="$f" 'length($0) > 60 {print name": line "FNR" is "length($0)" chars"}' "$f"; done; python3 -I -c '
import ast, sys
for path in ["rosterkit/notices.py", "tests/test_notices.py"]:
    tree = ast.parse(open(path).read())
    for node in ast.walk(tree):
        if isinstance(node, ast.FunctionDef):
            span = node.end_lineno - node.lineno + 1
            # signature starts at def line; decorators none here
            print(path, node.name, "lines:", span)
'; echo "== tests"; make check 2>&1 | tail -4; echo "== lint"; make lint 2>&1 | tail -2

